"""Generate EVALS.md from evals/results/*.json. Do not edit EVALS.md by hand."""
import json
from pathlib import Path

R = Path(__file__).resolve().parent / "results"
OUT = Path(__file__).resolve().parent.parent / "EVALS.md"


def load(n):
    p = R / n
    return json.loads(p.read_text(encoding="utf-8")) if p.exists() else None


def section(title, d, L):
    hs = d["households"]
    ok = sum(h["passed_all"] for h in hs)
    L += [f"## {title}", "", f"{ok}/{len(hs)} households passed in all {d['repeats']} repeats. Pass rule: record that is "
          "UNUSABLE per normalisation -> flagged to the officer and no advisory; otherwise -> advisory queued "
          "(auto-corrections are recorded on the advisory's officer note).", ""]
    cls = {}
    for h in hs:
        cls.setdefault(h["expected_class"], []).append(h["passed_all"])
    L += ["| Record class | Households | Passed |", "|---|---|---|"]
    for k, v in sorted(cls.items()):
        L.append(f"| {k} | {len(v)} | {sum(v)} |")
    inv = d["invariants_per_run"][0]
    L += ["", f"Safety invariants after each full run: advisories queued = {inv['advisories_queued']}; not in "
              f"PENDING_HUMAN_APPROVAL = {inv['advisories_not_pending']}; with a number absent from their evidence = "
              f"{inv['advisories_with_ungrounded_numbers']}; audit chain intact = {inv['audit_chain_ok']}.", ""]
    if d.get("recovery"):
        r = d["recovery"]
        L += [f"Recovery task ({r['id']}): first draft contains an invented figure -> server rejects "
              f"(`{', '.join(r['errors'])}`), the loop rewrites and queues. Result: **{'PASS' if r['passed'] else 'FAIL'}**.", ""]
    mean_s = sum(h["mean_seconds"] for h in hs) / len(hs)
    tin = sum(h["mean_input_tokens"] for h in hs) / len(hs)
    tout = sum(h["mean_output_tokens"] for h in hs) / len(hs)
    L += [f"Cost per household: ~{mean_s:.2f} s wall time, ~{tin:.0f} input / {tout:.0f} output tokens "
          "(local model: no API cost).", ""]
    bad = [h for h in hs if not h["passed_all"]]
    if bad:
        L += ["Households not passing every repeat:", "", "| Household | Class | Pass rate | Errors seen |", "|---|---|---|---|"]
        for h in bad:
            L.append(f"| {h['id']} | {h['expected_class']} | {h['pass_rate']} | {', '.join(h['errors_seen']) or '-'} |")
        L.append("")


def main():
    tools = load("tools.json")
    eps = {(f.stem.split("_", 1)[1]): json.loads(f.read_text(encoding="utf-8")) for f in sorted(R.glob("episodes_*.json"))}
    names = {"scripted_pipeline": "B1. Pipeline mode, non-LLM template writer (validates plumbing and guardrails only)",
             "scripted_agent": "B2. Agent mode, scripted non-LLM policy (validates plumbing and guardrails only)",
             "ollama_pipeline": "B3. Pipeline mode, open-weights LLM (Qwen via Ollama writes and rewrites the SMS)",
             "ollama_agent": "B4. Agent mode, open-weights LLM chooses every tool call"}
    L = ["# EVALS", "",
         "_Generated by `python evals/report.py` from `evals/results/*.json`. Every number below comes from a run "
         "of `evals/run_evals.py`; nothing is hand-written. 'Today' is pinned to "
         f"{(tools or next(iter(eps.values()), {})).get('today_fixed', '2026-10-12')} for reproducibility. "
         "Development-time observations with the 7B model are in `LLM_DEV_LOG.md` (hand-written, not scored)._", "",
         "## What was and was not evaluated", "", "| Layer | Status |", "|---|---|",
         f"| A. Tool + guardrail tests over real MCP stdio, no LLM | {'run, ' + str(len(tools['tasks'])) + ' tasks x ' + str(tools['repeats']) if tools else 'not run'} |"]
    for k, title in names.items():
        L.append(f"| {title} | {'run, ' + str(len(eps[k]['households'])) + ' households x ' + str(eps[k]['repeats']) if k in eps else '**NOT RUN**'} |")
    L += ["", "Modes: in *pipeline* mode the code chooses the tool calls and the LLM drafts and rewrites the SMS; in "
          "*agent* mode the LLM chooses every call. Scripted rows prove the system around the model works; only "
          "B3/B4 say anything about the LLM. Not evaluated at all: accuracy of rainfall, irrigation and price figures "
          "against real observations (datasets are simulated) and usefulness to farmers.", ""]
    if tools:
        L += ["## A. Tool and guardrail tests", "",
              "| ID | Scenario | Expected | Result | Runs passed | Same output each run |", "|---|---|---|---|---|---|"]
        for t in tools["tasks"]:
            L.append(f"| {t['id']} | {t['title']} | {t['expected']} | **{'PASS' if t['passed'] else 'FAIL'}** | "
                     f"{t['passes']} | {'yes' if t['stable_across_runs'] else 'NO'} |")
        L.append("")
    for k, title in names.items():
        if k in eps:
            section(title, eps[k], L)
    if tools:
        fails = [t for t in tools["tasks"] if not t["passed"]]
        L += ["## Unfixed failure", ""]
        if not fails:
            L += ["No failing task in this run.", ""]
        for t in fails:
            L += [f"### {t['id']}: {t['title']}", "",
                  f"Expected: {t['expected']}. Observed: `{json.dumps(t['observed'], ensure_ascii=False)}`.", "",
                  "Cause: sowing windows are only encoded where an extension advisor confirmed them (so far Zou, "
                  "maize: March-April and August-September; `sowing_windows.py`). For every other department/crop "
                  "the season is NOT checked and the rain-scenario generator (`engine.generate_scenarios`) draws a "
                  "120-day rainy-season profile indexed from day 1 of the season, ignoring the calendar sowing date. "
                  "A 15 December sowing in Borgou therefore still gets a normal-looking plan; the output says "
                  "`season_check: not_covered` but the call is not blocked.", "",
                  "What I would try next: collect windows per department and crop from advisors (one interview per "
                  "zone), store them with their source, and make `plan_irrigation` refuse when a zone has no data "
                  "and the month is in the dry season; align scenario days to calendar dates using the M2 profiles' "
                  "start dates."]
    OUT.write_text("\n".join(L), encoding="utf-8")
    print("wrote", OUT)


if __name__ == "__main__":
    main()
